<div class="page-actions"><a class="back-link" href="<?= site_url('admin/wilayah') ?>">← Master wilayah</a><?php if ($can_create): ?><a class="button button-dark" href="<?= site_url('admin/wilayah/'.$level.'/tambah') ?>">+ Tambah wilayah</a><?php endif; ?></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari wilayah</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Kode atau nama"></label><?php if ($level!=='province'): ?><?php $selector_id='region-parent-filter';$selector_name='parent_id';$selector_until=array('regency'=>'province','district'=>'regency','village'=>'district')[$level];$selected_ids[$selector_until]=$parent_id;$this->load->view('regions/selector',compact('selector_id','selector_name','selector_until','selected_ids','provinces')); ?><?php endif; ?><label><span>Status</span><select name="status"><option value="">Semua</option><option value="aktif" <?= $p['status']==='aktif'?'selected':'' ?>>Aktif</option><option value="arsip" <?= $p['status']==='arsip'?'selected':'' ?>>Arsip</option></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small" type="submit">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Kode Kemendagri</th><th>Nama wilayah</th><th>Induk</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td class="mono"><?= h($r['code']) ?></td><td><strong><?= h($r['name']) ?></strong><?php if ($r['village_type']): ?><small class="cell-sub"><?= h(ucfirst($r['village_type'])) ?></small><?php endif; ?></td><td><?= h($r['parent_name']?:'—') ?><small class="cell-sub mono"><?= h($r['parent_code']??'') ?></small></td><td><span class="pill <?= $r['active']?'pill-green':'pill-muted' ?>"><?= $r['active']?'Aktif':'Arsip' ?></span></td><td class="actions-cell"><?php if ($can_edit): ?><a class="row-link" href="<?= site_url('admin/wilayah/'.$level.'/'.$r['id'].'/ubah') ?>">Ubah</a><?php endif; ?><?php if ($can_archive): ?><form method="post" action="<?= site_url('admin/wilayah/'.$level.'/'.$r['id'].'/status') ?>" onsubmit="return confirm('Ubah status wilayah ini?')"><?= csrf_input() ?><button class="text-button" type="submit"><?= $r['active']?'Arsipkan':'Aktifkan' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="empty-cell">Tidak ada wilayah yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
